"type" : "string" , "description" : "The reason why the agent is yielding control to the human." } }, "required" : [ "reason" ] } } interaction = client . interactions . create ( model = "gemini-3.7-flash" , input = "Click the submit button. If you need a second factor authentication code, ask me." , tools = [ { "type" : "computer_use" , "environment" : "mobile" , "excluded_predefined_functions" : [ "click" ] }, yield_to_user_tool ] ) JavaScript להחריג פעולות סטנדרטיות שהוגדרו מראש בדפדפן (כמו click ) ולרשום כלי מותאם אישית yield_to_user : import { GoogleGenAI } from '@google/genai' ; const ai = new GoogleGenAI (); const yieldToUserTool = { type : "function" , name : "yield_to_user" , description : "Yields control back to the user for assistance or verification when an automated action is unsafe or ambiguous." , parameters : { type : "object" , properties : { reason : { type : "string" , description : "The reason why the agent is yielding control to the human." } }, required : [ "reason" ] } }; const interaction = await ai . interactions . create ({ model : "gemini-3.7-flash" , input : "Click the submit button. If you need a second factor authentication code, ask me." , tools : [ { type : "computer_use" , environment : "mobile" , excluded_predefined_functions : [ "click" ] }, yieldToUserTool ] }); כלים מותאמים אישית של Gemini 2.5 (גרסה מדור קודם) Python from google import genai client = genai . Client () # Define custom tools here custom_functions = [ ... ] # Describe parameters as function declarations excluded_functions = [ "open_web_browser" , "wait_5_seconds" , "go_back" , "go_forward" , "search" , "navigate" , "hover_at" , "scroll_document" , "key_combination" , "drag_and_drop" , ] interaction = client . interactions . create ( model = 'gemini-2.5-computer-use-preview-10-2025' , input = "Open Chrome, then long-press at 200,400." , tools = [ { "type" : "computer_use" , "environment" : "browser" , "excluded_predefined_functions" : excluded_functions }, * custom_functions ] ) print ( interaction ) JavaScript import { GoogleGenAI } from '@google/genai' ; const ai = new GoogleGenAI (); // Define custom tools here const customFunctions = [...]; // Describe parameters as function declarations const excludedFunctions = [ "open_web_browser" , "wait_5_seconds" , "go_back" , "go_forward" , "search" , "navigate" , "hover_at" , "scroll_document" , "key_combination" , "drag_and_drop" , ]; const interaction = await ai . interactions . create ({ model : 'gemini-2.5-computer-use-preview-10-2025' , input : "Open Chrome, then long-press at 200,400." , tools : [ { type : "computer_use" , environment : "browser" , excluded_predefined_functions : excludedFunctions }, ... customFunctions ] }); console . log ( interaction ); ניהול רמות ההעמקה (Gemini 3.x) בסוכנים לשימוש במחשב, אפשר להגדיר רמות חשיבה שונות כדי ליצור איזון בין איכות הפעולה למהירות הביצוע. בדרך כלל, רמות חשיבה נמוכות יותר מאפשרות להשיג איזון טוב במשימות אוטומציה רגילות. בטיחות ואבטחה הגדרת מדיניות בנושא בטיחות (Gemini 3.x) מודלים של Gemini 3.x כוללים קטגוריות מוּבְנות של שירותי בטיחות שקובעות באופן אוטומטי אם נדרש אישור מהמשתמש. קטגוריית מדיניות בנושא בטיחות תיאור FINANCIAL_TRANSACTIONS חסימה או הפעלה של אישור לפעולות שקשורות לתשלומים, לתשלום בקמעונאות או למוצרים מפוקחים. SENSITIVE_DATA_MODIFICATION הגנה על רשומות בריאותיות, פיננסיות או ממשלתיות מפני שינויים לא מורשים. COMMUNICATION_TOOL הגבלה של הסוכן כך שלא יוכל לשלוח אימיילים, הודעות צ&#39;אט או טיוטות באופן אוטונומי. ACCOUNT_CREATION ההגדרה הזו מגבילה את הסוכן ומונעת ממנו לרשום באופן אוטונומי חשבונות חדשים באתרים. DATA_MODIFICATION ההרשאה הזו מסדירה שינויים במערכת הקבצים, שיתוף נתונים ומחיקת אחסון. USER_CONSENT_MANAGEMENT נדרשת השתלטות על המשתמשים כדי להציג באנרים לבקשת הסכמה לשימוש בקובצי Cookie והודעות בנושא פרטיות. LEGAL_TERMS_AND_AGREEMENTS מונעת מהמודל לאשר באופן אוטונומי תנאים והגבלות או חוזים מחייבים מבחינה משפטית. שינויים בהגדרות האבטחה אפשר לשנות מדיניות ספציפית על ידי העברת שינויים: הערה: אמצעי הבטיחות לביטול הגדרות מציינים את ההעדפה שלכם, אבל יכול להיות שהמודל עדיין יחזיר safety_decision עם require_confirmation במקרים מסוימים. האפליקציה שלך צריכה תמיד להטמיע טיפול בהחלטות בנושא בטיחות, ללא קשר לשינויים שהוגדרו. Python from google import genai client = genai . Client () interaction = client . interactions . create ( model = "gemini-3.7-flash" , input = "Clean up the local folder by archiving old logs." , tools = [ { "type" : "computer_use" , "environment" : "desktop" , "disabled_safety_policies" : [ "data_modification" ] } ] ) JavaScript import { GoogleGenAI } from '@google/genai' ; const ai = new GoogleGenAI (); const interaction = await ai . interactions . create ({ model : "gemini-3.7-flash" , input : "Clean up the local folder by archiving old logs." , tools : [ { type : "computer_use" , environment : "desktop" , disabled_safety_policies : [ "data_modification" ] } ] }); זיהוי החדרת פרומפטים (Gemini 3.x) מנגנון בטיחות אופציונלי שסורק פיקסלים בצילומי מסך כדי לזהות הוראות פרומפט זדוני נסתרות (למשל, &quot;התעלם מהפקודות הקודמות&quot;) וחוסם את הביצוע שלהן אם הן מזוהות. אישור החלטה בנושא בטיחות התשובה יכולה לכלול את הפרמטר safety_decision בארגומנטים של קריאת הפונקציה: { "steps" : [ { "type" : "function_call" , "name" : "click_at" , "arguments" : { "x" : 60 , "y" : 100 , "safety_decision" : { "explanation" : "Must check check-box" , "decision" : "require_confirmation" } } } ] } אם הערך של safety_decision הוא require_confirmation , מציגים למשתמש הקצה הנחיה. אם המשתמש מאשר, מגדירים את safety_acknowledgement ב- function_result . Python def get_safety_confirmation ( safety_decision ): # Prompt user for confirmation print ( f "Safety confirmation required: { safety_decision . get ( 'explanation' , '' ) } " ) return "CONTINUE" # Or TERMINATE # Inside execute_function_calls, check for safety_decision: if 'safety_decision' in function_call . arguments : decision = get_safety_confirmation ( function_call . arguments [ 'safety_decision' ]) if decision == "TERMINATE" : break # Include safety_acknowledgement inside the action result action_result [ "safety_acknowledgement" ] = True שיטות מומלצות לשמירה על האבטחה שימוש במחשב מציב סיכוני אבטחה ותפעול ייחודיים, כי מודל שפועל בשם משתמש עלול להיתקל בתוכן לא מהימן במסכים או לבצע שגיאות בהפעלת פעולות. כדי להגן על נתוני המשתמשים ועל המערכות, מומלץ להטמיע את השיטות המומלצות הבאות: Human-in-the-Loop (HITL): אכיפת אישור המשתמש: אם התגובה בנושא בטיחות מציינת require_confirmation (או אם נדרש אישור לפי החלטת הבטיחות הקודמת), המשתמש יתבקש לאשר. הוספת הוראות בטיחות בהתאמה אישית: אפשר להטמיע הוראות מערכת בהתאמה אישית כדי להגדיר ולאכוף את גבולות הבטיחות שלכם. לדוגמה: Python from google import genai client = genai . Client () system_instruction = """ ## **RULE 1: Seek User Confirmation (USER_CONFIRMATION)** This is your first and most important check. If the next required action falls into any of the following categories, you MUST stop immediately, and seek the user's explicit permission. **Procedure for Seeking Confirmation:** * **For Consequential Actions:** Perform all preparatory steps (e.g., navigating, filling out forms, typing a message). You will ask for confirmation **AFTER** all necessary information is entered on the screen, but **BEFORE** you perform the final, irreversible action (e.g., before clicking "Send", "Submit", "Confirm Purchase", "Share"). * **For Prohibited Actions:** If the action is strictly forbidden (e.g., accepting legal terms, solving a CAPTCHA), you must first inform the user about the required action and ask for their confirmation to proceed. **USER_CONFIRMATION Categories:** * **Consent and Agreements:** You are FORBIDDEN from accepting, selecting, or agreeing to any of the following on the user's behalf. You must ask the user to confirm before performing these actions. * Terms of Service * Privacy Policies * Cookie consent banners * End User License Agreements (EULAs) * Any other legally significant contracts or agreements. * **Robot Detection:** You MUST NEVER attempt to solve or bypass the following. You must ask the user to confirm before performing these actions. * CAPTCHAs (of any kind) * Any other anti-robot or human-verification mechanisms, even if you are capable. * **Financial Transactions:** * Completing any purchase. * Managing or moving money (e.g., transfers, payments). * Purchasing regulated goods or participating in gambling. * **Sending Communications:** * Sending emails. * Sending messages on any platform (e.g., social media, chat apps). * Posting content on social media or forums. * **Accessing or Modifying Sensitive Information:** * Health, financial, or government records (e.g., medical history, tax forms, passport status). * Revealing or modifying sensitive personal identifiers (e.g., SSN, bank account number, credit card number). * **User Data Management:** * Accessing, downloading, or saving files from the web. * Sharing or sending files/data to any third party. * Transferring user data between systems. * **Browser Data Usage:** * Accessing or managing Chrome browsing history, bookmarks, autofill data, or saved passwords. * **Security and Identity:** * Logging into any user account. * Any action that involves misrepresentation or impersonation (e.g., creating a fan account, posting as someone else). * **Insurmountable Obstacles:** If you are technically unable to interact with a user interface element or are stuck in a loop you cannot resolve, ask the user to take over. --- ## **RULE 2: Default Behavior (ACTUATE)** If an action does **NOT** fall under the conditions for `USER_CONFIRMATION`, your default behavior is to **Actuate**. **Actuation Means:** You MUST proactively perform all necessary steps to move the user's request forward. Continue to actuate until you either complete the non-consequential task or encounter a condition defined in Rule 1. * **Example 1:** If asked to send money, you will navigate to the payment portal, enter the recipient's details, and enter the amount. You will then **STOP** as per Rule 1 and ask for confirmation before clicking the final "Send" button. * **Example 2:** If asked to post a message, you will navigate to the site, open the post composition window, and write the full message. You will then **STOP** as per Rule 1 and ask for confirmation before clicking the final "Post" button. After the user has confirmed, remember to get the user's latest screen before continuing to perform actions. # Final Response Guidelines: Write final response to the user in the following cases: - User confirmation - When the task is complete or you have enough information to respond to the user """ interaction = client . interactions . create ( model = "gemini-3.7-flash" , system_instruction = system_instruction , input = "Prepare a draft but do not send." , tools = [{ "type" : "computer_use" , "environment" : "browser" }] ) JavaScript import { GoogleGenAI } from '@google/genai' ; const ai = new GoogleGenAI (); const systemInstruction = ` ## **RULE 1: Seek User Confirmation (USER_CONFIRMATION)** This is your first and most important check. If the next required action falls into any of the following categories, you MUST stop immediately, and seek the user's explicit permission. **Procedure for Seeking Confirmation:** * **For Consequential Actions:** Perform all preparatory steps (e.g., navigating, filling out forms, typing a message). You will ask for confirmation **AFTER** all necessary information is entered on the screen, but **BEFORE** you perform the final, irreversible action (e.g., before clicking "Send", "Submit", "Confirm Purchase", "Share"). * **For Prohibited Actions:** If the action is strictly forbidden (e.g., accepting legal terms, solving a CAPTCHA), you must first inform the user about the required action and ask for their confirmation to proceed. **USER_CONFIRMATION Categories:** * **Consent and Agreements:** You are FORBIDDEN from accepting, selecting, or agreeing to any of the following on the user's behalf. You must ask the user to confirm before performing these actions. * Terms of Service * Privacy Policies * Cookie consent banners * End User License Agreements (EULAs) * Any other legally significant contracts or agreements. * **Robot Detection:** You MUST NEVER attempt to solve or bypass the following. You must ask the user to confirm before performing these actions. * CAPTCHAs (of any kind) * Any other anti-robot or human-verification mechanisms, even if you are capable. * **Financial Transactions:** * Completing any purchase. * Managing or moving money (e.g., transfers, payments). * Purchasing regulated goods or participating in gambling. * **Sending Communications:** * Sending emails. * Sending messages on any platform (e.g., social media, chat apps). * Posting content on social media or forums. * **Accessing or Modifying Sensitive Information:** * Health, financial, or government records (e.g., medical history, tax forms, passport status). * Revealing or modifying sensitive personal identifiers (e.g., SSN, bank account number, credit card number). * **User Data Management:** * Accessing, downloading, or saving files from the web. * Sharing or sending files/data to any third party. * Transferring user data between systems. * **Browser Data Usage:** * Accessing or managing Chrome browsing history, bookmarks, autofill data, or saved passwords. * **Security and Identity:** * Logging into any user account. * Any action that involves misrepresentation or impersonation (e.g., creating a fan account, posting as someone else). * **Insurmountable Obstacles:** If you are technically unable to interact with a user interface element or are stuck in a loop you cannot resolve, ask the user to take over. --- ## **RULE 2: Default Behavior (ACTUATE)** If an action does **NOT** fall under the conditions for ` USER_CONFIRMATION `, your default behavior is to **Actuate**. **Actuation Means:** You MUST proactively perform all necessary steps to move the user's request forward. Continue to actuate until you either complete the non-consequential task or encounter a condition defined in Rule 1. * **Example 1:** If asked to send money, you will navigate to the payment portal, enter the recipient's details, and enter the amount. You will then **STOP** as per Rule 1 and ask for confirmation before clicking the final "Send" button. * **Example 2:** If asked to post a message, you will navigate to the site, open the post composition window, and write the full message. You will then **STOP** as per Rule 1 and ask for confirmation before clicking the final "Post" button. After the user has confirmed, remember to get the user's latest screen before continuing to perform actions. # Final Response Guidelines: Write final response to the user in the following cases: - User confirmation - When the task is complete or you have enough information to respond to the user ` ; const interaction = await ai . interactions . create ({ model : "gemini-3.7-flash" , system_instruction : systemInstruction , input : "Prepare a draft but do not send." , tools : [{ type : "computer_use" , environment : "browser" }] }); סביבת ביצוע מאובטחת: הפעלת הסוכן בסביבה מאובטחת של ארגז חול כדי להגביל את ההשפעה הפוטנציאלית שלו. יכול להיות שמדובר במכונה וירטואלית (VM) בסביבת ארגז חול, בקונטיינר (למשל, Docker) או בפרופיל דפדפן ייעודי עם הרשאות מוגבלות. הוראות להגדרת ארגז חול באמצעות Docker מופיעות ב הטמעה לדוגמה ב-GitHub . ניקוי קלט: ניקוי של כל הטקסט שנוצר על ידי משתמשים בהנחיות, כדי לצמצם את הסיכון להוראות לא מכוונות או להחדרת פרומפטים. זו שכבת אבטחה מועילה, אבל היא לא תחליף לסביבת ביצוע מאובטחת. אמצעי הגנה על תוכן: אפשר להשתמש באמצעי הגנה ובממשקי API של בטיחות תוכן כדי להעריך את הקלט של המשתמשים, את הקלט והפלט של כלי העזר ואת התשובות של הסוכן, ולבדוק אם הם מתאימים, אם יש בהם הזרקת הנחיות ואם הם מאפשרים עקיפת הגבלות. רשימות היתרים ורשימות חסימה: כדאי להטמיע מנגנוני סינון כדי לשלוט במיקומים שבהם המודל יכול לנווט ובפעולות שהוא יכול לבצע. רשימת חסימה של אתרים אסורים היא נקודת התחלה טובה, אבל רשימת היתרים מגבילה יותר ומספקת אבטחה טובה יותר. יכולת מעקב ורישום ביומן: שמירה של יומנים מפורטים לצורך ניפוי באגים, ביקורת ותגובה לאירועים. הלקוח צריך לתעד הנחיות, צילומי מסך, פעולות שהמודל מציע ( function_call ), תגובות שקשורות לבטיחות וכל הפעולות שהלקוח מבצע בסופו של דבר. ניהול סביבה: מוודאים שהסביבה של ממשק המשתמש הגרפי עקבית. חלונות קופצים, התראות או שינויים בפריסה שלא ציפיתם להם עלולים לבלבל את המודל. אם אפשר, מתחילים ממצב נקי ומוכר לכל משימה חדשה. גרסאות המודלים אפשר להשתמש ב&#39;שימוש במחשב&#39; עם המודלים הבאים: ‫ Gemini 3.7 Flash ( gemini-3.7-flash ): המודל המומלץ לשימוש במחשב, עם פעולות יעילות באמצעות כוונות, תמיכה בסביבות דפדפן, נייד ושולחן עבודה, מדיניות אבטחה שניתנת להגדרה וזיהוי של הזרקת הנחיות. ‫ Gemini 3.5 Flash-Lite ( gemini-3.5-flash-lite ): מודל חסכוני עם זמן אחזור נמוך, שתומך בשימוש במחשב. ‫ Gemini 3.5 Flash ( gemini-3.5-flash ): מודל יציב קודם שתומך בשימוש במחשב. ‫ Gemini 3 Flash Preview ( gemini-3-flash-preview ): מודל בתצוגה מקדימה עם תמיכה בשימוש במחשב. ‫ Gemini 2.5 (גרסת טרום-השקה מדור קודם) ( gemini-2.5-computer-use-preview-10-2025 ): מודל טרום-השקה מדור קודם שעבר אופטימיזציה לשימוש במחשב מבוסס-דפדפן. המאמרים הבאים אפשר להתנסות בשימוש במחשב ב סביבת ההדגמה של Browserbase . בדף Reference implementation יש דוגמאות לקוד. מידע על כלים אחרים של Gemini API: בקשה להפעלת פונקציה עיגון באמצעות חיפוש Google שליחת משוב אלא אם צוין אחרת, התוכן של דף זה הוא ברישיון Creative Commons Attribution 4.0 ודוגמאות הקוד הן ברישיון Apache 2.0 . לפרטים, ניתן לעיין ב מדיניות האתר Google Developers‏ .‏ Java הוא סימן מסחרי רשום של חברת Oracle ו/או של השותפים העצמאיים שלה. עדכון אחרון: 2026-08-19 (שעון UTC). רוצה לתת לנו משוב? [[["התוכן קל להבנה","easyToUnderstand","thumb-up"],["התוכן עזר לי לפתור בעיה","solvedMyProblem","thumb-up"],["סיבה אחרת","otherUp","thumb-up"]],[["חסרים לי מידע או פרטים","missingTheInformationINeed","thumb-down"],["התוכן מורכב מדי או עם יותר מדי שלבים","tooComplicatedTooManySteps","thumb-down"],["התוכן לא עדכני","outOfDate","thumb-down"],["בעיה בתרגום","translationIssue","thumb-down"],[